#include <unistd.h>
int	main(int ac,char **av){int i=0;int start;int first_end;if(ac<2){write(1,"\n",1);return(0);}while(av[1][i]==' '||av[1][i]=='\t')i++;start=i;while(av[1][i]&&av[1][i]!=' '&&av[1][i]!='\t')i++;first_end=i;while(av[1][i]==' '||av[1][i]=='\t')i++;while(av[1][i]){if(av[1][i]==' '||av[1][i]=='\t'){while(av[1][i]==' '||av[1][i]=='\t')i++;if(av[1][i])write(1," ",1);}else write(1,&av[1][i++],1);}if(i>first_end)write(1," ",1);write(1,av[1]+start,first_end-start);write(1,"\n",1);return(0);}
